mapper.sql:
WHERE t.user_id = #{userId}
  AND t.transaction_type = 'PAYMENT'
  AND t.transacted_at >= #{condition.startDateTime}
  AND t.transacted_at < #{condition.endDateTime}

mapper.select:
SELECT
    ec.expense_category_id AS category_id,
    ec.category_name,
    COALESCE(SUM(CASE
        WHEN t.transacted_at >= #{previousMonthStartDateTime}
            AND t.transacted_at < #{currentMonthStartDateTime}
        THEN t.amount ELSE 0 END), 0) AS previous_month_amount,
    COALESCE(SUM(CASE
        WHEN t.transacted_at >= #{currentMonthStartDateTime}
            AND t.transacted_at < #{currentMonthEndDateTime}
        THEN t.amount ELSE 0 END), 0) AS current_month_amount
FROM expense_category ec
LEFT JOIN `transaction` t
    ON t.expense_category_id = ec.expense_category_id
    AND t.user_id = #{userId}
    AND t.transaction_type = 'PAYMENT'
    AND t.transacted_at >= #{previousMonthStartDateTime}
    AND t.transacted_at < #{currentMonthEndDateTime}
GROUP BY ec.expense_category_id, ec.category_name
ORDER BY ec.expense_category_id ASC
